export type BuildingKind = 'inn' | 'shop' | 'elder' | 'kura' | 'house' | 'smithy';

/** A building on solid H tiles: footprint in tiles, door on the south side. */
export interface Building {
  kind: BuildingKind;
  x: number;
  y: number;
  w: number;
  h: number;
}

export type VillagerRole = 'talk' | 'shop' | 'inn';

export interface Villager {
  x: number;
  y: number;
  role: VillagerRole;
  /** Index into the town's talk lines (role 'talk'). */
  lines: number[];
  look: 'elder' | 'girl' | 'smith' | 'merchant' | 'keeper';
}

export interface VillageDef {
  map: string[];
  buildings: Building[];
  villagers: Villager[];
}

